import{_ as o,o as i,c as a,a4 as t}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0007 — Image de base Python pour apps/api : python:3.12-alpine","description":"Extrait de docs/adr/0007-image-base-python-api-alpine.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0007 — Image de base Python pour apps/api : python:3.12-alpine","description":"Extrait de docs/adr/0007-image-base-python-api-alpine.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0007-image-base-python-api-alpine.md","filePath":"developpeurs/adr/0007-image-base-python-api-alpine.md"}'),n={name:"developpeurs/adr/0007-image-base-python-api-alpine.md"};function c(s,e,d,r,l,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0007--image-de-base-python-pour-appsapi--python312-alpine" tabindex="-1">ADR-0007 — Image de base Python pour <code>apps/api</code> : <code>python:3.12-alpine</code> <a class="header-anchor" href="#adr-0007--image-de-base-python-pour-appsapi--python312-alpine" aria-label="Permalink to &quot;ADR-0007 — Image de base Python pour `apps/api` : `python:3.12-alpine` {#adr-0007--image-de-base-python-pour-appsapi--python312-alpine}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> vérification demandée en suite de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0006-image-base-node-admin-alpine">ADR-0006</a> (même exercice, appliqué à <code>apps/api/Dockerfile</code>).</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Contrairement à <code>apps/admin</code>, aucune alerte Docker DX n&#39;a été signalée sur <code>apps/api/Dockerfile</code> (<code>python:3.12-slim</code>). Vérification faite par précaution, en miroir de l&#39;ADR-0006 :</p><ul><li><strong><code>docker scout cves</code></strong> : toujours indisponible (authentification Docker Hub requise, non faisable dans cet environnement).</li><li><strong>Recherche publique (Sliplane CVE scanner, tags actuels)</strong> : <ul><li><code>python:3.12-slim</code> : <strong>0 critique, 0 haute</strong>, 2 moyennes, 20 basses.</li><li><code>python:3.12-alpine</code> : <strong>0 critique, 0 haute</strong>, 2 moyennes (CVE-2025-60876, CVE-2025-8869), 2 basses.</li></ul></li><li><strong>Conclusion CVE : pas d&#39;urgence.</strong> À la différence de <code>node:22-slim</code> (ADR-0006), <code>python:3.12-slim</code> n&#39;a aujourd&#39;hui aucune vulnérabilité critique/haute connue — rien à corriger dans l&#39;immédiat.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Basculer quand même vers <code>python:3.12-alpine</code>, épinglé par digest, sur <code>apps/api/Dockerfile</code>.</strong> Motivé non par une urgence CVE mais par :</p><ul><li><strong>Réduction de surface</strong> : image ~18 Mo contre ~43 Mo pour <code>slim</code> (test local, même jour) — moins de paquets système, donc moins de futures CVE potentielles.</li><li><strong>Harmonisation</strong> avec <code>apps/admin</code> (ADR-0006) : même stratégie de base d&#39;image sur les deux services du monorepo, même mécanisme de rafraîchissement (Renovate).</li><li><strong>Coût de migration nul, vérifié empiriquement</strong> : <code>asyncpg</code>, <code>uvloop</code>, <code>httptools</code>, <code>sqlalchemy</code> (greenlet), <code>pydantic-core</code>, <code>watchfiles</code>, <code>websockets</code>, <code>pyyaml</code>, <code>markupsafe</code>, <code>ruff</code> publient tous des wheels <code>musllinux_1_x_x86_64</code> — <code>pip install -e &quot;.[dev]&quot;</code> s&#39;installe intégralement depuis des wheels précompilées, <strong>sans aucune compilation native</strong>.</li></ul><p><strong>Constat additionnel</strong> : le bloc <code>apt-get install libpq-dev gcc</code> du Dockerfile d&#39;origine était déjà superflu. <code>asyncpg</code> implémente le protocole PostgreSQL nativement (il ne link pas contre <code>libpq</code>), et aucune autre dépendance du projet ne nécessite de compilation — confirmé par un build de test sans aucun outil de compilation installé, réussi du premier coup. Ce bloc est supprimé (il n&#39;aurait de toute façon pas de sens sous Alpine, dont le gestionnaire de paquets est <code>apk</code>, pas <code>apt-get</code>).</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Ne rien changer</strong> (<code>python:3.12-slim</code> est propre)</td><td>Écartée car demandée explicitement par Bastien pour harmoniser avec <code>apps/admin</code> — le coût de migration étant nul (build/démarrage validés), le gain de surface reste positif même sans urgence CVE.</td></tr><tr><td><strong><code>gcr.io/distroless/python3-debian12</code></strong></td><td>Même raisonnement que pour <code>apps/admin</code> (ADR-0006) : registre tiers hors Docker Hub, pas de shell pour le debug, gain marginal ici. Non retenue pour rester cohérent avec le choix Alpine déjà fait sur <code>apps/admin</code>.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Image ~2,4× plus légère (18 Mo vs 43 Mo), déploiements plus rapides.</li><li>Un seul type de base d&#39;image (Alpine) à surveiller/rafraîchir sur tout le monorepo, via le même <code>renovate.json</code> (aucune modification de config nécessaire : le manager <code>dockerfile</code> de Renovate couvre déjà tous les <code>Dockerfile</code> du repo).</li><li>Dockerfile simplifié (suppression d&#39;un bloc <code>apt-get</code> qui ne servait à rien).</li></ul><p><strong>Négatives</strong></p><ul><li>Même limite que pour <code>apps/admin</code> (ADR-0006) : <code>musl</code> diffère de <code>glibc</code>, une future dépendance sans wheel musllinux forcerait soit un retour à <code>slim</code>, soit l&#39;ajout d&#39;<code>apk add build-base</code> + compilation source (plus lent en CI).</li><li>Digest épinglé (<code>sha256:d09d15e60962ca365d1cd544a48773bac9d33f2fb1b00f2aa0deec78ade7dc31</code>, vérifié le 19 août 2026) : mêmes conséquences que pour <code>apps/admin</code>, rafraîchissement délégué à Renovate (déjà en place, pas de configuration supplémentaire requise).</li></ul><h2 id="mise-à-jour--vérification-appsapitests--ci-et-ordre-copypip-install" tabindex="-1">Mise à jour — vérification <code>apps/api/tests</code> + CI, et ordre COPY/pip install <a class="header-anchor" href="#mise-à-jour--vérification-appsapitests--ci-et-ordre-copypip-install" aria-label="Permalink to &quot;Mise à jour — vérification `apps/api/tests` + CI, et ordre COPY/pip install {#mise-à-jour--vérification-appsapitests--ci-et-ordre-copypip-install}&quot;">​</a></h2><p>Vérification demandée après coup : rejouer <code>apps/api/tests</code> et le job CI <code>api</code> avec ces changements.</p><ul><li><strong>Bug préexistant découvert, sans rapport avec cette ADR</strong> : le job CI <code>api</code> était rouge sur <code>main</code> depuis le premier commit Sprint 0 — son service <code>postgres:16-alpine</code> ne fournit pas l&#39;extension <code>pgvector</code> qu&#39;exige la migration <code>0001</code> (<code>CREATE EXTENSION IF NOT EXISTS vector</code>), contrairement à <code>docker-compose.yml</code> qui utilise <code>pgvector/pgvector:pg16</code>. Confirmé par les logs GitHub Actions réels (<code>gh run view --log-failed</code>) et reproduit à l&#39;identique avec l&#39;ancien Dockerfile <code>slim</code> — donc <strong>pas une régression</strong> de la bascule Alpine. Corrigé séparément dans <code>.github/workflows/ci.yml</code>.</li><li><strong>Bug latent trouvé en creusant</strong> : <code>pytest</code> exécuté seul <em>dans</em> l&#39;image (<code>docker run &lt;image&gt; pytest</code>) échouait avec <code>ModuleNotFoundError: No module named &#39;app&#39;</code>, sur l&#39;ancien Dockerfile comme sur le nouveau. Cause : <code>RUN pip install -e &quot;.[dev]&quot;</code> s&#39;exécutait avant <code>COPY . .</code>, donc au moment de l&#39;install éditable, le paquet <code>app/</code> n&#39;existait pas encore sur disque — hatchling ne l&#39;enregistre alors nulle part (<code>import app</code> ne fonctionnait par accident que grâce au <code>cwd=/app</code> inséré dans <code>sys.path</code>, jamais grâce à l&#39;editable install). <strong>Corrigé</strong> : <code>COPY . .</code> passe avant <code>RUN pip install -e &quot;.[dev]&quot;</code>. Coût assumé : le layer <code>pip install</code> n&#39;est plus mis en cache indépendamment du code source (tout changement de code réinstalle les dépendances) — acceptable au stade actuel du projet.</li><li><strong>Validé</strong> (build réel avec digest épinglé, réseau Docker + <code>pgvector/pgvector:pg16</code>, ordre CI reproduit fidèlement) : <code>ruff check .</code> ✓, <code>alembic upgrade head</code> (4 migrations) ✓, <code>pytest -q</code> <strong>21/21</strong> ✓ — y compris en invoquant <code>pytest</code> nu (plus seulement <code>python -m pytest</code>) — et <code>/health</code> répond <code>200</code>.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Modifier <code>apps/api/Dockerfile</code> : <code>python:3.12-slim</code> → <code>python:3.12-alpine</code>, digest épinglé.</li><li>[x] Supprimer le bloc <code>apt-get install libpq-dev gcc</code> (superflu, confirmé par test).</li><li>[x] Valider le build et <code>/health</code> en local (sans DB, sans variables d&#39;environnement).</li><li>[x] Vérifier que <code>renovate.json</code> couvre déjà ce Dockerfile — aucune modification requise (<code>matchManagers: [&quot;dockerfile&quot;, ...]</code> s&#39;applique à tous les <code>Dockerfile</code> du repo).</li><li>[x] Corriger <code>.github/workflows/ci.yml</code> : <code>postgres:16-alpine</code> → <code>pgvector/pgvector:pg16</code> (bug préexistant, sans rapport avec cette ADR).</li><li>[x] Inverser l&#39;ordre <code>COPY . .</code> / <code>pip install -e &quot;.[dev]&quot;</code> dans <code>apps/api/Dockerfile</code> pour que l&#39;editable install fonctionne indépendamment du <code>cwd</code>.</li></ul>',21)])])}const g=o(n,[["render",c]]);export{m as __pageData,g as default};
